import base64
import json
import os
from typing import Any, Dict, List, Optional

import boto3


def _to_text(value: Any) -> str:
    if value is None:
        return ""
    if isinstance(value, (str, int, float, bool)):
        return str(value)
    if isinstance(value, dict):
        for key in ("Text", "text", "Value", "value", "Content", "content", "DetectedText"):
            if key in value and value[key] is not None:
                return _to_text(value[key])
        return json.dumps(value, ensure_ascii=False)
    if isinstance(value, list):
        return " ".join(_to_text(v) for v in value if _to_text(v))
    return str(value)


def _get_field_value(field: Any) -> str:
    if field is None:
        return ""
    if isinstance(field, dict):
        for key in ("Value", "Text", "Content", "amount", "currency"):
            if key in field and field[key] is not None:
                if key == "amount":
                    return _to_text(field[key])
                if key == "currency":
                    return _to_text(field[key])
                return _to_text(field[key])
        if "ValueString" in field and field["ValueString"] is not None:
            return _to_text(field["ValueString"])
        if "ValueCurrency" in field and field["ValueCurrency"] is not None:
            vc = field["ValueCurrency"]
            if isinstance(vc, dict):
                amount = _to_text(vc.get("Amount"))
                currency = _to_text(vc.get("CurrencyCode"))
                return f"{amount} {currency}".strip()
            return _to_text(vc)
    return _to_text(field)


def _extract_items(line_items: List[Dict[str, Any]]) -> List[Dict[str, Any]]:
    items: List[Dict[str, Any]] = []
    for item in line_items or []:
        if not isinstance(item, dict):
            continue
        product = ""
        quantity = ""
        unit_price = ""
        price = ""
        tax = ""

        fields = item.get("LineItemExpenseFields", []) or []
        for f in fields:
            if not isinstance(f, dict):
                continue
            ftype = _to_text(f.get("Type", {}).get("Text") if isinstance(f.get("Type"), dict) else f.get("Type")).lower()
            value = _get_field_value(f.get("ValueDetection") or f.get("Value") or f)
            if "item" in ftype or "description" in ftype or "product" in ftype:
                product = value or product
            elif "quantity" in ftype or ftype == "qty":
                quantity = value or quantity
            elif "unit" in ftype and "price" in ftype:
                unit_price = value or unit_price
            elif "price" in ftype or "amount" in ftype or "total" in ftype:
                price = value or price
            elif "tax" in ftype:
                tax = value or tax

        items.append(
            {
                "description": product,
                "quantity": quantity,
                "unit_price": unit_price,
                "price": price,
                "tax": tax,
            }
        )
    return items


def extract_receipt(document_bytes: bytes, content_type: str = "application/pdf") -> Dict[str, Any]:
    """
    Extract merchant, tax, total, and items from a receipt using Amazon Textract AnalyzeExpense.
    Requires AWS credentials configured in the environment.
    """
    textract = boto3.client("textract")

    response = textract.analyze_expense(
        Document={"Bytes": document_bytes},
    )

    expense_docs = response.get("ExpenseDocuments", []) or []
    first_doc = expense_docs[0] if expense_docs else {}

    summary_fields = first_doc.get("SummaryFields", []) or []
    line_item_groups = first_doc.get("LineItemGroups", []) or []

    merchant = ""
    tax = ""
    total = ""

    for field in summary_fields:
        if not isinstance(field, dict):
            continue
        ftype = _to_text(field.get("Type", {}).get("Text") if isinstance(field.get("Type"), dict) else field.get("Type")).lower()
        value = _get_field_value(field.get("ValueDetection") or field.get("Value") or field)

        if ftype in {"vendor_name", "merchant", "supplier_name"} and not merchant:
            merchant = value
        elif "tax" in ftype and not tax:
            tax = value
        elif ftype in {"total", "amount_due", "amount_paid", "invoice_total"} and not total:
            total = value

    if not merchant:
        for field in summary_fields:
            if not isinstance(field, dict):
                continue
            ftype = _to_text(field.get("Type", {}).get("Text") if isinstance(field.get("Type"), dict) else field.get("Type")).lower()
            if "name" in ftype or "vendor" in ftype or "merchant" in ftype:
                merchant = _get_field_value(field.get("ValueDetection") or field.get("Value") or field)
                if merchant:
                    break

    items: List[Dict[str, Any]] = []
    for group in line_item_groups:
        if isinstance(group, dict):
            items.extend(_extract_items(group.get("LineItems", []) or []))

    return {
        "merchant": merchant,
        "tax": tax,
        "total": total,
        "items": items,
        "raw_provider_response": response,
    }
